from itertools import product

def gains(H, path):
    """The gains sum_k H_k * (move k). H lists H_1..H_n; path is a string of H and T."""
    return sum(h * (1 if t == 'H' else -1) for h, t in zip(H, path))

def is_predictable(strategy, n):
    """True when strategy(path, k) depends only on path[:k-1], for k = 1..n."""
    paths = [''.join(p) for p in product('HT', repeat=n)]
    for k in range(1, n + 1):
        seen = {}
        for w in paths:
            key = w[:k - 1]
            v = strategy(w, k)
            if seen.setdefault(key, v) != v:
                return False
    return True
